import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from './back-button'

export const revalidate = 300
export const dynamicParams = true

type Post = {
  id: number
  title: string
  body: string
}

type Comment = {
  id: number
  name: string
  body: string
  email: string
}

type Params = Promise<{ id: string }>

async function getPostData(
  id: string
): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`),
    ])

    if (!postRes.ok) return null

    const [post, comments] = await Promise.all([
      postRes.json() as Promise<Post>,
      commentsRes.json() as Promise<Comment[]>,
    ])

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts: Post[] = await res.json()

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: {
  params: Params
}): Promise<Metadata> {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    return { title: 'Post Not Found - My Blog' }
  }

  const description = data.post.body.substring(0, 160)

  return {
    title: `${data.post.title} - My Blog`,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: { params: Params }) {
  const { id } = await params
  const data = await getPostData(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

