type Post = {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

type UpdatePostBody = {
  title?: string
  content?: string
}

type Params = Promise<{ id: string }>

export async function GET(
  _request: Request,
  { params }: { params: Params }
): Promise<Response> {
  const { id } = await params

  const post: Post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: { params: Params }
): Promise<Response> {
  const { id } = await params
  const { title, content }: UpdatePostBody = await request.json()

  const updatedPost: Post = {
    id: parseInt(id, 10),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: { params: Params }
): Promise<Response> {
  const { id } = await params
  return Response.json({ message: `Post ${id} deleted successfully` })
}

